text:
Here's a water tracker with a goal of 8 glasses. Tap a glass or use + and − to log, and it resets each day if your screen keeps it saved.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; text-align: center; padding: 24px; background: #f2f9fc; color: #14425a; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #count { font-size: 44px; font-weight: 600; margin: 12px 0 4px; }
  #msg { margin-bottom: 16px; min-height: 22px; }
  #glasses { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 360px; margin: 0 auto 20px; }
  .g { width: 64px; height: 84px; border: 3px solid #4aa3c7; border-radius: 6px 6px 16px 16px; background: #fff; cursor: pointer; padding: 0; position: relative; overflow: hidden; }
  .g.full::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; top: 14%; background: #5bc0eb; }
  .bar { height: 10px; max-width: 360px; margin: 0 auto 20px; background: #d6ebf3; border-radius: 5px; overflow: hidden; }
  #fill { height: 100%; width: 0; background: #2f9ac7; transition: width .25s; }
  button.c { font-size: 20px; width: 48px; height: 48px; border-radius: 24px; border: 0; background: #2f9ac7; color: #fff; cursor: pointer; margin: 0 6px; }
  button.r { border: 0; background: none; color: #14425a; text-decoration: underline; cursor: pointer; margin-top: 18px; font-size: 14px; }
  #day { font-size: 13px; opacity: .7; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="day"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div class="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div>
    <button class="c" id="minus">−</button>
    <button class="c" id="plus">+</button>
  </div>
  <button class="r" id="reset">Start over</button>

<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}

  document.getElementById("day").textContent = new Date().toDateString();

  var box = document.getElementById("glasses");
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var b = document.createElement("button");
      b.className = "g";
      b.onclick = function () { n = (n === i + 1) ? i : i + 1; draw(); };
      box.appendChild(b);
    })(i);
  }

  function draw() {
    if (n < 0) n = 0;
    if (n > 20) n = 20;
    try { localStorage.setItem(key, String(n)); } catch (e) {}
    var gl = box.children;
    for (var i = 0; i < GOAL; i++) gl[i].className = "g" + (i < n ? " full" : "");
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var left = GOAL - n;
    document.getElementById("msg").textContent =
      left > 0 ? left + (left === 1 ? " glass" : " glasses") + " to go" : "Goal reached. Nice work! 💧";
  }

  document.getElementById("plus").onclick = function () { n++; draw(); };
  document.getElementById("minus").onclick = function () { n--; draw(); };
  document.getElementById("reset").onclick = function () { n = 0; draw(); };
  draw();
</script>
</body>
</html>
```

